scwin.checkVal = function() {
	const attr_readonly = (document.getElementById('wq_uuid_1___input') || document.getElementById('mf_wq_uuid_1___input')).parentNode.getAttribute('readonly')				
	const attr_disabled = (document.getElementById('wq_uuid_1___input') || document.getElementById('mf_wq_uuid_1___input')).parentNode.getAttribute('disabled')
	return attr_readonly === null && attr_disabled === null;
}
